package junitdemo;

import org.junit.jupiter.api.Test;

import junitdemo.SequentialSearch;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.fail;

class AppTest {

        @Test
        @SuppressWarnings("CallToPrintStackTrace")
        public void testSequentialSearchIn(){
            int[] numbers = {12, 34, 5, 89, 21, 7};
            int target1 = 89;
            try{
            assertEquals(3, SequentialSearch.search(numbers, target1));
            } catch (Exception e){
                fail("An exception occured when runnng search");
                e.printStackTrace();
            }
        }

                @Test
        @SuppressWarnings("CallToPrintStackTrace")
        public void testSequentialSearchNotIn(){
            int[] numbers = {12, 34, 5, 89, 21, 7};
            int target1 = 0;
            try{
            assertEquals(-1, SequentialSearch.search(numbers, target1));
            } catch (Exception e){
                fail("An exception occured when runnng search");
                e.printStackTrace();
            }
        }

}
